/**
 * The files a worker created or changed, as the trusted verifier captured them at freeze (PRD_VIEWER_CLARITY 4.1): every
 * changed text file within the caps is a `file` artifact carrying its repo-relative `path`; every other changed file is
 * listed in `files_not_captured` with the reason. Results recorded before capture carry neither. Pure helpers and one
 * hook, kept out of the component files so those only export components.
 */
import { useCallback } from 'react'
import { fetchWorkerResult, scopedResultPath, type RunDetail, type RunScope, type WorkerResult } from './api.ts'
import { useResource } from './useResource.ts'

type SnapshotNode = RunDetail['snapshot']['nodes'][number]
type Artifact = WorkerResult['artifacts'][number]
export type CapturedFile = Artifact & { kind: 'file'; path: string }
export type NotCapturedFile = NonNullable<WorkerResult['files_not_captured']>[number]

export const NOT_CAPTURED_WORDING: Record<NotCapturedFile['reason'], string> = {
  binary: 'binary file, not captured',
  too_large: 'too large to capture (over the per-file size cap)',
  missing: 'deleted or renamed away in the snapshot, nothing to capture',
  budget: "not captured: the packet's capture budget was already spent",
}

export function capturedFiles(result: WorkerResult): CapturedFile[] {
  return result.artifacts.filter((artifact): artifact is CapturedFile => artifact.kind === 'file' && typeof artifact.path === 'string')
}

export function notCapturedFiles(result: WorkerResult): NotCapturedFile[] {
  return result.files_not_captured ?? []
}

/** Whether the result records file capture at all; a result without either list predates it. */
export function recordsCapture(result: WorkerResult): boolean {
  return capturedFiles(result).length > 0 || result.files_not_captured !== undefined
}

export function isMarkdownPath(path: string): boolean {
  return /\.md$/i.test(path)
}

/** The element id of a captured file's panel on the launch node, the target of a finding's file link. */
export function fileAnchorId(path: string): string {
  return `file-${path.replace(/[^A-Za-z0-9_-]/g, '_')}`
}

/**
 * Every captured file of a run, by path, with the launch node that shows it. Read from the launch nodes' own served worker
 * results through the run's scoped results route; nothing is inferred for a lane whose result is absent or failed to load.
 */
export function useRunCapturedFiles(scope: RunScope, snapshotNodes: SnapshotNode[], refreshToken: number): Map<string, string> {
  const launches = snapshotNodes.flatMap(node => {
    if (node.kind !== 'worker' || node.result_uri === null) return []
    const path = scopedResultPath(scope, node.result_uri)
    return path === null ? [] : [{ nodeId: node.node_id, path }]
  })
  // The launches are serialised into the resource key, so the loader only changes when the linked results do.
  const spec = JSON.stringify(launches)
  const load = useCallback(async (signal: AbortSignal) => {
    const list = JSON.parse(spec) as typeof launches
    const settled = await Promise.allSettled(list.map(async launch => ({ nodeId: launch.nodeId, result: await fetchWorkerResult(scope, launch.path, signal) })))
    const byPath = new Map<string, string>()
    for (const entry of settled) {
      if (entry.status !== 'fulfilled') continue
      for (const file of capturedFiles(entry.value.result)) if (!byPath.has(file.path)) byPath.set(file.path, entry.value.nodeId)
    }
    return byPath
  }, [scope, spec])
  const key = launches.length === 0 ? null : `captured:${spec}`
  const { state } = useResource(key, load, refreshToken)
  return state.status === 'ready' ? state.data : EMPTY
}

const EMPTY: Map<string, string> = new Map()

export function ProjectsView({ route, refreshToken, onNavigate, onAnnounce }: Props) {
  const projectId = route && route.level !== 'projects' ? route.projectId : null
  const workflowId = route && (route.level === 'workflow' || route.level === 'run') ? route.workflowId : null
  const runId = route && route.level === 'run' ? route.runId : null
  const nodeId = route && route.level === 'run' ? route.nodeId : null

  const { state: projects, reload: reloadProjects } = useResource('projects', fetchProjects, refreshToken)
  const loadWorkflows = useCallback((signal: AbortSignal) => fetchWorkflows(projectId!, signal), [projectId])
  const { state: workflows, reload: reloadWorkflows } = useResource(projectId === null ? null : `workflows:${projectId}`, loadWorkflows, refreshToken)
  const loadRuns = useCallback((signal: AbortSignal) => fetchRuns(projectId!, workflowId!, {}, signal), [projectId, workflowId])
  const runsKey = workflowId === null ? null : `runs:${projectId}/${workflowId}`
  // Run lists and run details re-read themselves while shown (a finished run no longer changes). A list that has
  // appended pages stops polling, since a new first page would drop them.
  const [morePages, setMorePages] = useState<{ base: RunPage | null; pages: RunPage[]; loading: boolean; error: unknown }>({ base: null, pages: [], loading: false, error: null })
  const [finished, setFinished] = useState(false)
  const listPoll = usePoll(route?.level === 'workflow' && morePages.pages.length === 0)
  const runPoll = usePoll(route?.level === 'run' && !finished)
  const { state: firstPage, reload: reloadRuns } = useResource(runsKey, loadRuns, refreshToken, listPoll)
  const scope = useMemo(() => (projectId === null || workflowId === null || runId === null ? null : { projectId, workflowId, runId }), [projectId, workflowId, runId])
  const loadDetail = useCallback((signal: AbortSignal) => fetchRunDetail({ projectId: projectId!, workflowId: workflowId!, runId: runId! }, signal), [projectId, workflowId, runId])
  const { state: detail, reload: reloadDetail } = useResource(scope === null ? null : `run:${scope.projectId}/${scope.workflowId}/${scope.runId}`, loadDetail, refreshToken, runPoll)
  const detailStatus = detail.status === 'ready' ? detail.data.summary.status : null
  useEffect(() => { setFinished(detailStatus === 'succeeded' || detailStatus === 'cancelled') }, [detailStatus])

  // Additional run pages are appended on demand; they belong to exactly one loaded first page and are dropped with it.
  const firstPageData = firstPage.status === 'ready' ? firstPage.data : null
  const extra = morePages.base !== null && morePages.base === firstPageData ? morePages : { base: firstPageData, pages: [], loading: false, error: null }
  const pages: RunPage[] = firstPageData ? [firstPageData, ...extra.pages] : []
  const runs: RunSummary[] = pages.flatMap(page => page.runs)
  const nextCursor = pages.length ? pages[pages.length - 1].nextCursor : null
  const loadMore = async () => {
    if (!nextCursor || projectId === null || workflowId === null || firstPageData === null) return
    setMorePages({ ...extra, base: firstPageData, loading: true, error: null })
    try {
      const page = await fetchRuns(projectId, workflowId, { cursor: nextCursor })
      setMorePages(previous => (previous.base === firstPageData ? { ...previous, pages: [...previous.pages, page], loading: false } : previous))
    } catch (error) {
      setMorePages(previous => (previous.base === firstPageData ? { ...previous, loading: false, error } : previous))
    }
  }

  const projectName = projects.status === 'ready' && projectId !== null ? projects.data.find(project => project.project_id === projectId)?.name ?? projectId : projectId
  const currentWorkflow = workflows.status === 'ready' && workflowId !== null ? workflows.data.find(workflow => workflow.workflow_id === workflowId) ?? null : null
  const workflowName = currentWorkflow?.name ?? workflowId

  // A background poll re-announces only what changed; a load the reader started (navigation, Refresh) always announces.
  const announced = useRef<string | null>(null)
  useEffect(() => {
    let message: string | null = null
    if (route === null) message = 'This Projects link is invalid.'
    else if (route.level === 'projects' && projects.status === 'ready') message = `Loaded ${projects.data.length} ${projects.data.length === 1 ? 'project' : 'projects'}.`
    else if (route.level === 'project' && workflows.status === 'ready') message = `Loaded ${workflows.data.length} ${workflows.data.length === 1 ? 'workflow' : 'workflows'} for ${projectName ?? route.projectId}.`
    else if (route.level === 'workflow' && firstPage.status === 'ready') message = `Loaded ${firstPage.data.runs.length} ${firstPage.data.runs.length === 1 ? 'run' : 'runs'} for ${workflowName ?? route.workflowId}.`
    else if (route.level === 'run' && detail.status === 'ready') message = `Loaded run ${route.runId}: ${detail.data.summary.status.replace('_', ' ')}.`
    else if ((projects.status === 'error') || workflows.status === 'error' || firstPage.status === 'error' || detail.status === 'error') message = 'Loading failed.'
    if (message === null) { announced.current = null; return }
    if (message === announced.current) return
    announced.current = message
    onAnnounce(message)
  }, [route, projects, workflows, firstPage, detail, projectName, workflowName, onAnnounce])

  const crumbs: PathCrumb[] = [{ id: 'home', label: 'Home', pathname: '/' }, { id: 'projects', label: 'Projects', pathname: projectsPathname() }]
